    /*
     * Add to the Variants
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	LandingGear
     */
    public LandingGear addToVariants( UUID parentId, AircraftVariant addTo ) {
	    LOGGER.info("handling AssignVariantsToLandingGearEvent - " );
	    
	    LandingGear parentEntity = repository.findById(parentId).get();
	    AircraftVariant child = registry.project( AircraftVariant.class, addTo.getAircraftVariantId());
	    
	    parentEntity.getVariants().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Variants
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	LandingGear
     */
	public LandingGear removeFromVariants( UUID parentId, AircraftVariant removeFrom ) {
	    LOGGER.info("handling RemoveVariantsFromLandingGearEvent " );
	
	    LandingGear parentEntity = repository.findById(parentId).get();
	    AircraftVariant child = registry.project( AircraftVariant.class, removeFrom.getAircraftVariantId());
	    
	    parentEntity.getVariants().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



